begin;
select plan(46);

select has_type('public','booking_confirmation_operation_state','confirmation operation state exists');
select enum_has_labels('public','booking_confirmation_operation_state',array['READY','INSERTING','FINALIZED'],'operation states make insertion authority explicit');
select has_table('public','appointment','appointment table exists');
select has_table('public','appointment_google_event','Google synchronization relation exists');
select has_table('public','booking_confirmation_operation','durable confirmation operation exists');
select ok((select relrowsecurity from pg_class where oid='public.booking_confirmation_operation'::regclass),'operation RLS enabled');
select ok(not has_table_privilege('service_role','public.booking_confirmation_operation','select'),'service role uses guarded operation RPCs');
select has_function('public','claim_public_booking_confirmation',array['text','text','text','timestamp with time zone'],'claim RPC exists');
select has_function('public','begin_public_booking_confirmation_insert',array['text','uuid','timestamp with time zone'],'insert fence RPC exists');
select has_function('public','finalize_public_booking_confirmation',array['text','uuid','uuid','text','text','text','timestamp with time zone'],'leased finalization RPC exists');
select hasnt_function('public','reset_public_booking_confirmation_insert',array['text','uuid','timestamp with time zone'],'INSERTING has no reset RPC');
select has_function('public','mark_booking_confirmation_reauth_required',array['uuid','uuid','bigint'],'generation-aware reauth RPC exists');
select ok(has_function_privilege('service_role','public.claim_public_booking_confirmation(text,text,text,timestamptz)','execute'),'service role can claim');
select ok(has_function_privilege('service_role','public.begin_public_booking_confirmation_insert(text,uuid,timestamptz)','execute'),'service role can fence insert');
select ok(not has_function_privilege('anon','public.claim_public_booking_confirmation(text,text,text,timestamptz)','execute'),'anonymous browser cannot claim directly');
select ok(not has_function_privilege('authenticated','public.finalize_public_booking_confirmation(text,uuid,uuid,text,text,text,timestamptz)','execute'),'authenticated browser cannot finalize');
select is((select proconfig from pg_proc where oid='public.claim_public_booking_confirmation(text,text,text,timestamptz)'::regprocedure),array['search_path=""'],'claim fixes an empty search path');
select is((select count(*) from pg_constraint where conrelid='public.booking_confirmation_operation'::regclass and contype='u' and pg_get_constraintdef(oid) ilike '%calendar_id%event_id%'),1::bigint,'provider identity is unique per calendar');

set local role service_role;
select lives_ok($setup$
 insert into public.customer(id,studio_id,name,status) values('60000000-0000-0000-0000-000000000040','20000000-0000-0000-0000-000000000001','Confirmation client','ACTIVE');
 insert into public.tattoo_case(id,studio_id,customer_id,summary,artist_profile_id,status) values('70000000-0000-0000-0000-000000000040','20000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000040','Private confirmation case','50000000-0000-0000-0000-000000000001','OPEN');
 select public.activate_google_calendar_connection('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','v1.confirmation-ciphertext.tag',array['https://www.googleapis.com/auth/calendar.calendarlist.readonly','https://www.googleapis.com/auth/calendar.events.freebusy','https://www.googleapis.com/auth/calendar.events']);
 select public.assign_artist_calendar('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','artist-a@example.test','writer');
 create temporary table confirmation_connection as select id,credential_generation from public.get_google_calendar_connection('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001');
 create temporary table confirmation_offer as select (public.create_booking_offer('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000040','50000000-0000-0000-0000-000000000001','[{"startUtc":"2026-09-20T09:00:00.000Z","endUtc":"2026-09-20T10:00:00.000Z"}]','2026-09-15T10:00:00Z')->>'id')::uuid offer_id;
 select public.rotate_booking_offer_public_access('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',(select offer_id from confirmation_offer),repeat('56',32),'2026-09-15T10:01:00Z');
 create temporary table confirmation_selector as select public.get_public_booking_offer(repeat('56',32),'2026-09-15T10:02:00Z')->'options'->0->>'selector' selector;
 select public.select_public_booking_offer(repeat('56',32),(select selector from confirmation_selector),'2026-09-15T10:03:00Z');
 create temporary table confirmation_claim as select public.claim_public_booking_confirmation(repeat('56',32),'inkendar0123456789abc',repeat('C',43),'2026-09-15T10:04:00Z') value;
$setup$,'synthetic pending selection can establish a durable claim');
select is((select value->>'kind' from confirmation_claim),'CLAIMED','first worker owns the claim');
select is((select value->>'mode' from confirmation_claim),'INSERT_OR_RECONCILE','new operation may insert after reconciliation');
select is((select value->>'calendar_id' from confirmation_claim),'artist-a@example.test','claim binds the original calendar');
select ok(((select value->>'lease_id' from confirmation_claim)::uuid) is not null,'claim has an opaque lease');
select is(public.claim_public_booking_confirmation(repeat('56',32),'inkendar0123456789abc',repeat('C',43),'2026-09-15T10:04:30Z')->>'kind','BUSY','concurrent worker cannot reach Google effects');
select is(public.begin_public_booking_confirmation_insert(repeat('56',32),'90000000-0000-4000-8000-000000000001','2026-09-15T10:05:00Z'),false,'wrong lease cannot acquire insert authority');
select is(public.begin_public_booking_confirmation_insert(repeat('56',32),(select (value->>'lease_id')::uuid from confirmation_claim),'2026-09-15T10:05:00Z'),true,'owner acquires insertion authority exactly once');
select is(public.begin_public_booking_confirmation_insert(repeat('56',32),(select (value->>'lease_id')::uuid from confirmation_claim),'2026-09-15T10:05:01Z'),false,'repeated begin cannot authorize a second insert');
reset role;
select is((select state::text from public.booking_confirmation_operation where booking_offer_id=(select offer_id from confirmation_offer)),'INSERTING','insert fence is durable');
set local role service_role;
select lives_ok($$select public.assign_artist_calendar('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','artist-b@example.test','writer')$$,'assignment may change after the external-effect binding');
select lives_ok($$create temporary table recovery_claim as select public.claim_public_booking_confirmation(repeat('56',32),'inkendar0123456789abc',repeat('C',43),'2026-09-15T10:07:01Z') value$$,'expired inserting lease is recoverable');
select is((select value->>'mode' from recovery_claim),'RECONCILE_ONLY','crash recovery may only reconcile');
select is((select value->>'calendar_id' from recovery_claim),'artist-a@example.test','recovery ignores changed assignment and keeps calendar A');
select is(public.begin_public_booking_confirmation_insert(repeat('56',32),(select (value->>'lease_id')::uuid from recovery_claim),'2026-09-15T10:07:02Z'),false,'recovery lease can never authorize a second insert');
select is(public.finalize_public_booking_confirmation(repeat('56',32),(select (value->>'lease_id')::uuid from recovery_claim),(select id from confirmation_connection),'artist-a@example.test','inkendar0123456789abc',repeat('C',43),'2026-09-15T10:08:00Z')->>'confirmed_at','2026-09-15T10:08:00+00:00','reconciled original event finalizes atomically');
reset role;
select is((select status::text from public.booking_offer where id=(select offer_id from confirmation_offer)),'CONFIRMED','offer becomes confirmed');
select is((select count(*) from public.appointment where booking_offer_id=(select offer_id from confirmation_offer)),1::bigint,'one appointment exists');
select is((select count(*) from public.appointment_google_event event join public.appointment appointment on appointment.id=event.appointment_id where appointment.booking_offer_id=(select offer_id from confirmation_offer)),1::bigint,'one sync relation exists');
select is((select state::text from public.booking_confirmation_operation where booking_offer_id=(select offer_id from confirmation_offer)),'FINALIZED','operation records finalization');
set local role service_role;
select lives_ok($$create temporary table finalized_claim as select public.claim_public_booking_confirmation(repeat('56',32),'inkendar0123456789abc',repeat('C',43),'2026-09-15T10:09:00Z') value$$,'confirmed retry can reclaim for reconciliation');
select is((select value->>'mode' from finalized_claim),'RECONCILE_ONLY','confirmed retry remains reconciliation-only');
select is(public.finalize_public_booking_confirmation(repeat('56',32),(select (value->>'lease_id')::uuid from finalized_claim),(select id from confirmation_connection),'artist-a@example.test','inkendar0123456789abc',repeat('C',43),'2026-09-15T10:09:01Z')->>'confirmed_at','2026-09-15T10:08:00+00:00','idempotent retry preserves original timestamp');
select throws_ok($$select public.claim_public_booking_confirmation(repeat('56',32),'inkendar0123456789abd',repeat('C',43),'2026-09-15T10:12:00Z')$$,'P0003',null,'provider identity mismatch fails closed');
select is(public.get_public_booking_offer(repeat('56',32),'2026-09-17T10:00:00Z')->>'state','CONFIRMED','confirmed view survives offer expiry');
select is(public.expire_booking_offers('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','2026-09-17T10:00:00Z'),0,'expiry leaves confirmed offers untouched');
select is((select count(*) from public.list_active_booking_holds('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','2026-09-20T00:00:00Z','2026-09-21T00:00:00Z','2026-09-17T10:00:00Z')),1::bigint,'confirmed interval remains the single availability exclusion');
select throws_ok($$select public.create_booking_offer('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000040','50000000-0000-0000-0000-000000000001','[{"startUtc":"2026-09-20T09:30:00.000Z","endUtc":"2026-09-20T10:30:00.000Z"}]','2026-09-17T10:00:00Z')$$,'23P01',null,'new holds cannot overlap the confirmed interval');

select * from finish();
rollback;
